        Res second = call("POST", "/orders", cart("20000000002", "{\"sku\":\"MOC-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "BRONZE", "SOUTH"));
        String id2 = second.body().get("id").asString();

